WITH claim_summary AS (SELECT policy_id,COUNT(*) claim_count,SUM(claim_amount) claim_amount,SUM(approved_amount) approved_amount,MAX(fraud_flag) fraud_signal FROM claims GROUP BY policy_id), risk AS (SELECT policy_id,MAX(risk_score) risk_score,MAX(risk_band) risk_band FROM risk_assessments GROUP BY policy_id)
SELECT p.policy_type,p.geography,COALESCE(r.risk_band,p.risk_band) risk_band,COUNT(*) policies,SUM(p.premium_amount) premium,COALESCE(SUM(c.claim_amount),0) claims,COALESCE(SUM(c.approved_amount),0) approved,AVG(COALESCE(r.risk_score,0)) avg_risk_score,SUM(COALESCE(c.fraud_signal,0)) fraud_signals FROM policies p LEFT JOIN claim_summary c ON p.policy_id=c.policy_id LEFT JOIN risk r ON p.policy_id=r.policy_id GROUP BY p.policy_type,p.geography,COALESCE(r.risk_band,p.risk_band) ORDER BY fraud_signals DESC,claims DESC;
